<script setup lang="ts">import { computed } from 'vue'; import { useTaskCreation } from '@/composables/useTaskCreation'; import { useAppStore } from '@/stores/app'; import TaskRow from '@/components/task/TaskRow.vue'; import type { Category } from '@/types'; const props=defineProps<{category:Category}>(); const app=useAppStore(); const { openCreateTask }=useTaskCreation(); const backlog=computed(()=>app.tasks.filter(t=>t.categoryId===props.category.id&&t.status==='Backlog'))</script>
<template><section class="panel"><div class="panel-header"><div><h2>Backlog</h2><p>Work that has not been scheduled yet.</p></div><button class="btn btn-primary" @click="openCreateTask({categoryId:category.id})">Create task</button></div><div v-if="backlog.length" class="task-list"><TaskRow v-for="t in backlog" :key="t.id" :task="t"/></div><div v-else class="empty-state"><h3>No backlog items</h3><p>Everything has either been scheduled or, against all statistical probability, completed.</p></div></section></template>
